// Unwrap webhook body, normalize form fields across notification types, validate, and decode the recipients file.
const body = ($input.first().json.body) || {};

const form = {
  notification_type: String(body.notification_type || 'data_breach').toLowerCase(),
  company_name: body.company_name || '',
  sender_name: body.sender_name || '',
  sender_email: body.sender_email || '',
  contact_email: body.contact_email || '',
  contact_phone: body.contact_phone || '',
  incident_date: body.incident_date || body.breach_date || '',
  jurisdiction: body.jurisdiction || '',
  description: body.description || body.breach_description || '',
  data_exposed: body.data_exposed || '',
  company_response: body.company_response || '',
  recommended_actions: body.recommended_actions || '',
  additional_info: body.additional_info || '',
  notification_deadline: body.notification_deadline || '',
  regulatory_requirements: body.regulatory_requirements || '',
  report_recipient_email: body.report_recipient_email || '',
  custom_subject: body.custom_subject || '',
  custom_body: body.custom_body || '',
  test_mode: body.test_mode === true || body.test_mode === 'true' || body.test_mode === 'on' || body.test_mode === '1',
  file_name: (body.recipients_file && body.recipients_file.name) ? String(body.recipients_file.name) : ''
};

// Required field validation
const required = ['company_name', 'sender_name', 'sender_email', 'contact_email', 'report_recipient_email'];
const missing = required.filter(function (f) { return !String(form[f]).trim(); });
if (missing.length) {
  throw new Error('Missing required form fields: ' + missing.join(', '));
}
if (!body.recipients_file || !body.recipients_file.data) {
  throw new Error('No recipients file was uploaded (recipients_file.data is empty).');
}

// Decode base64 file to binary
const buf = Buffer.from(body.recipients_file.data, 'base64');
const lower = form.file_name.toLowerCase();
let mimeType = 'application/octet-stream';
if (lower.endsWith('.csv')) { mimeType = 'text/csv'; }
else if (lower.endsWith('.xlsx')) { mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'; }
else if (lower.endsWith('.xls')) { mimeType = 'application/vnd.ms-excel'; }

return [{
  json: form,
  binary: {
    data: {
      data: buf.toString('base64'),
      mimeType: mimeType,
      fileName: form.file_name || 'recipients.csv'
    }
  }
}];

// Validate emails, de-duplicate, and apply Test Mode limit.
const form = $('Parse and Validate Notification Data').first().json;
const cfg = $('Set Config Parameters').first().json;
const rows = $input.all().map(function (i) { return i.json; });
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

let skipped = 0;
let duplicates = 0;
const seen = new Set();
const valid = [];

for (const r of rows) {
  const email = String(r.email || '').trim().toLowerCase();
  if (!email || !emailRe.test(email)) { skipped++; continue; }
  if (seen.has(email)) { duplicates++; continue; }
  seen.add(email);
  const clean = Object.assign({}, r);
  clean.email = email;
  clean.name = String(r.name || '').trim();
  valid.push(clean);
}

let limited = valid;
if (form.test_mode) {
  const limit = Number(cfg.config_test_mode_limit) || 5;
  limited = valid.slice(0, limit);
}

if (!limited.length) {
  throw new Error('No valid recipients after validation. Rows: ' + rows.length + ', invalid/missing email: ' + skipped + ', duplicates: ' + duplicates);
}

return limited.map(function (r, i) {
  return { json: Object.assign({}, r, {
    _row: i + 1,
    _stats_total_rows: rows.length,
    _stats_skipped: skipped,
    _stats_duplicates: duplicates
  }) };
});

// Build the personalized notification for one recipient, using type presets or a custom body with {{tokens}}.
const form = $('Parse and Validate Notification Data').first().json;
const r = $json;

const presets = {
  data_breach: {
    label: 'Data Breach',
    subject: 'Important: Data Breach Notification - {{company_name}}',
    body: [
      'Dear {{name}},', '',
      'We are writing to inform you of a data security incident that may have affected your personal information.', '',
      'Date of Incident: {{incident_date}}',
      'Jurisdiction: {{jurisdiction}}', '',
      'WHAT HAPPENED:', '{{description}}', '',
      'INFORMATION INVOLVED:', '{{data_exposed}}', '',
      'WHAT WE ARE DOING:', '{{company_response}}', '',
      'WHAT YOU CAN DO:', '{{recommended_actions}}', '',
      'FOR MORE INFORMATION:',
      'Email: {{contact_email}}',
      'Phone: {{contact_phone}}', '',
      '{{additional_info}}', '',
      'We take the protection of your information seriously and sincerely apologize for any inconvenience this may cause.', '',
      'Sincerely,', '{{sender_name}}', '{{company_name}}'
    ].join('\n')
  },
  class_action: {
    label: 'Class Action Notice',
    subject: 'Legal Notice: You May Be Affected by a Class Action - {{company_name}}',
    body: [
      'Dear {{name}},', '',
      'This is an official legal notice. Our records indicate you may be a member of a class affected by the following matter.', '',
      'MATTER:', '{{description}}', '',
      'RELEVANT PERIOD / DATE:', '{{incident_date}}',
      'JURISDICTION:', '{{jurisdiction}}', '',
      'YOUR RIGHTS AND OPTIONS:', '{{recommended_actions}}', '',
      'IMPORTANT DEADLINE:', '{{notification_deadline}}', '',
      'ADDITIONAL INFORMATION:', '{{additional_info}}', '',
      'QUESTIONS:',
      'Email: {{contact_email}}',
      'Phone: {{contact_phone}}', '',
      'Sincerely,', '{{sender_name}}', '{{company_name}}'
    ].join('\n')
  },
  terms_update: {
    label: 'Terms Update',
    subject: 'Important Update to Our Terms - {{company_name}}',
    body: [
      'Dear {{name}},', '',
      'We are writing to let you know about upcoming changes to our terms and policies.', '',
      'WHAT IS CHANGING:', '{{description}}', '',
      'EFFECTIVE DATE:', '{{notification_deadline}}', '',
      'WHAT THIS MEANS FOR YOU:', '{{recommended_actions}}', '',
      '{{additional_info}}', '',
      'If you have questions, contact us at {{contact_email}}{{contact_phone}}.', '',
      'Sincerely,', '{{sender_name}}', '{{company_name}}'
    ].join('\n')
  },
  regulatory: {
    label: 'Regulatory Notice',
    subject: 'Important Regulatory Notice - {{company_name}}',
    body: [
      'Dear {{name}},', '',
      'We are required to provide you with the following notice.', '',
      'NOTICE:', '{{description}}', '',
      'JURISDICTION / AUTHORITY:', '{{jurisdiction}}',
      'REGULATORY REQUIREMENTS:', '{{regulatory_requirements}}', '',
      'WHAT YOU SHOULD DO:', '{{recommended_actions}}', '',
      'DEADLINE (IF APPLICABLE):', '{{notification_deadline}}', '',
      '{{additional_info}}', '',
      'Questions: {{contact_email}} {{contact_phone}}', '',
      'Sincerely,', '{{sender_name}}', '{{company_name}}'
    ].join('\n')
  },
  custom: {
    label: 'Notification',
    subject: '{{custom_subject}}',
    body: ''
  }
};

const typeKey = presets[form.notification_type] ? form.notification_type : 'data_breach';
const preset = presets[typeKey];

const ctx = Object.assign({}, form, r);
ctx.name = r.name || 'Valued Customer';

function render(tpl) {
  return String(tpl || '')
    .replace(/\{\{\s*(\w+)\s*\}\}/g, function (m, k) {
      const v = ctx[k];
      return (v === undefined || v === null) ? '' : String(v);
    })
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const hasCustomBody = String(form.custom_body || '').trim().length > 0;
const bodyTpl = hasCustomBody ? form.custom_body : preset.body;
if (!String(bodyTpl).trim()) {
  throw new Error('Notification type "custom" requires a custom_body from the form.');
}
const subjectTpl = String(form.custom_subject || '').trim() ? form.custom_subject : preset.subject;
let subject = render(subjectTpl);
if (!subject) { subject = 'Important Notice from ' + (form.company_name || 'Your Organization'); }

return {
  json: {
    to: r.email,
    subject: subject,
    body: render(bodyTpl),
    recipientName: ctx.name,
    recipientId: r.id || r._row,
    notification_type: typeKey,
    type_label: preset.label,
    timestamp: new Date().toISOString(),
    _stats_total_rows: r._stats_total_rows,
    _stats_skipped: r._stats_skipped,
    _stats_duplicates: r._stats_duplicates
  }
};

// Aggregate results from all batches (SplitInBatches 'done' output accumulates every looped item).
const items = $input.all();
const form = $('Parse and Validate Notification Data').first().json;
const cfg = $('Set Config Parameters').first().json;

const sent = items.filter(function (i) { return i.json.status === 'sent'; });
const failed = items.filter(function (i) { return i.json.status === 'failed'; });
const first = items.length ? items[0].json : {};
const typeLabel = first.type_label || 'Notification';

const times = items.map(function (i) { return new Date(i.json.timestamp).getTime(); }).filter(function (t) { return !isNaN(t); });
const startMs = times.length ? Math.min.apply(null, times) : Date.now();
const endMs = times.length ? Math.max.apply(null, times) : Date.now();

const byDomain = {};
sent.forEach(function (i) {
  const d = String(i.json.to || '').split('@')[1] || 'unknown';
  byDomain[d] = (byDomain[d] || 0) + 1;
});

const failures = failed.map(function (i) { return { to: i.json.to, error: i.json.error || 'unknown' }; });
const now = new Date();

const metrics = {
  campaign: {
    name: typeLabel + ' Notification Campaign',
    type: first.notification_type || form.notification_type,
    type_label: typeLabel,
    company: form.company_name || 'Unknown',
    incident_date: form.incident_date || 'N/A',
    notification_date: now.toISOString().split('T')[0],
    jurisdiction: form.jurisdiction || 'N/A'
  },
  summary: {
    total_rows_uploaded: first._stats_total_rows || items.length,
    valid_recipients: items.length,
    emails_sent: sent.length,
    emails_failed: failed.length,
    skipped_invalid: first._stats_skipped || 0,
    duplicates_removed: first._stats_duplicates || 0,
    batch_size: Number(cfg.config_batch_size) || 10,
    test_mode: form.test_mode === true
  },
  timing: {
    notification_start: new Date(startMs).toISOString(),
    notification_end: new Date(endMs).toISOString(),
    duration_minutes: Math.max(0, Math.round((endMs - startMs) / 60000))
  },
  compliance: {
    jurisdiction: form.jurisdiction || 'N/A',
    notification_deadline: form.notification_deadline || 'Not specified',
    regulatory_requirements: form.regulatory_requirements || 'Standard notification requirements apply'
  },
  recipient_breakdown: {
    by_domain: byDomain,
    failures: failures
  },
  report_metadata: {
    generated_at: now.toISOString(),
    generated_by: form.sender_name || 'System Administrator',
    report_recipient: form.report_recipient_email || form.sender_email
  }
};

return { json: { metrics: metrics } };

/**
 * Branded notification campaign report (flat, white background, Gotenberg-ready index.html).
 * Branding is driven by the Config — Settings node.
 */
const metrics = $input.first().json.metrics;
const cfg = $('Set Config Parameters').first().json;
const navy = cfg.config_brand_navy || '#002657';
const blue = cfg.config_brand_blue || '#0021a5';
const orange = cfg.config_brand_orange || '#fa4616';
const logoUrl = cfg.config_logo_url || '';
const reportTitle = metrics.campaign.type_label + ' Notification Report';
const dateStamp = metrics.campaign.notification_date;

const domainRows = Object.entries(metrics.recipient_breakdown.by_domain)
  .map(function (entry) {
    const pct = metrics.summary.emails_sent ? ((entry[1] / metrics.summary.emails_sent) * 100).toFixed(1) : '0.0';
    return '<tr><td style="padding:10px;border-bottom:1px solid #eee;">' + entry[0] + '</td>' +
      '<td style="padding:10px;border-bottom:1px solid #eee;">' + entry[1] + '</td>' +
      '<td style="padding:10px;border-bottom:1px solid #eee;font-weight:bold;color:' + blue + ';">' + pct + '%</td></tr>';
  }).join('');

const failureRows = metrics.recipient_breakdown.failures
  .map(function (f) {
    return '<tr><td style="padding:10px;border-bottom:1px solid #eee;">' + f.to + '</td>' +
      '<td style="padding:10px;border-bottom:1px solid #eee;color:#b00020;">' + String(f.error).substring(0, 200) + '</td></tr>';
  }).join('');

const failureSection = metrics.summary.emails_failed > 0
  ? '<div class="section"><h2>Delivery Failures</h2><table><thead><tr><th>Recipient</th><th>Error</th></tr></thead><tbody>' + failureRows + '</tbody></table></div>'
  : '';

const testBanner = metrics.summary.test_mode
  ? '<div style="background:#fff3e0;border-left:5px solid ' + orange + ';padding:12px 20px;margin-bottom:20px;font-weight:bold;">TEST MODE — only the first ' + metrics.summary.valid_recipients + ' recipients were processed.</div>'
  : '';

const htmlReport = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>' + reportTitle + ' - ' + metrics.campaign.company + '</title>' +
'<style>' +
'html,body{background:#fff !important;margin:0 !important;padding:0 !important;width:100% !important;box-shadow:none !important;}' +
'@page{margin:20mm;size:letter;}' +
'body{font-family:\'Helvetica Neue\',Helvetica,Arial,sans-serif;color:#343741;line-height:1.5;font-size:11pt;}' +
'.header-main{display:flex;justify-content:space-between;align-items:center;border-bottom:4px solid ' + orange + ';padding:20px 0;margin-bottom:30px;}' +
'.logo{height:60px;width:auto;}' +
'.section{margin:30px 0;}' +
'h2{color:' + navy + ';border-left:6px solid ' + blue + ';padding-left:15px;margin-bottom:15px;font-size:18pt;text-transform:uppercase;letter-spacing:-0.5px;}' +
'table{width:100%;border-collapse:collapse;margin:15px 0;}' +
'table th{background:' + navy + ';color:#fff;padding:12px 10px;text-align:left;text-transform:uppercase;font-size:10pt;}' +
'.metric-container{display:flex;justify-content:space-between;gap:15px;margin:20px 0;}' +
'.metric-box{flex:1;background:#f9f9f9;padding:20px;border-bottom:3px solid ' + blue + ';text-align:center;}' +
'.metric-value{font-size:24pt;font-weight:800;color:' + navy + ';margin-bottom:5px;}' +
'.metric-label{color:' + blue + ';font-size:9pt;font-weight:bold;text-transform:uppercase;}' +
'.footer{text-align:center;font-size:9pt;color:#999;margin-top:60px;border-top:1px solid #eee;padding-top:20px;}' +
'td{padding:10px;border-bottom:1px solid #eee;}' +
'</style></head><body>' +
'<div class="header-main">' + (logoUrl ? '<img src="' + logoUrl + '" class="logo" alt="logo">' : '<div></div>') +
'<div style="text-align:right;"><div style="color:' + navy + ';font-weight:800;font-size:14pt;">' + reportTitle.toUpperCase() + '</div>' +
'<div style="color:' + blue + ';font-size:10pt;">' + metrics.campaign.company + '</div></div></div>' +
testBanner +
'<div class="section"><h2>Campaign Summary</h2><div class="metric-container">' +
'<div class="metric-box"><div class="metric-value">' + metrics.summary.valid_recipients + '</div><div class="metric-label">Valid Recipients</div></div>' +
'<div class="metric-box"><div class="metric-value">' + metrics.summary.emails_sent + '</div><div class="metric-label">Emails Sent</div></div>' +
'<div class="metric-box"><div class="metric-value">' + metrics.summary.emails_failed + '</div><div class="metric-label">Failed</div></div>' +
'<div class="metric-box"><div class="metric-value">' + metrics.timing.duration_minutes + 'm</div><div class="metric-label">Duration</div></div>' +
'</div></div>' +
'<div class="section"><h2>Campaign Details</h2><table><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody>' +
'<tr><td>Notification Type</td><td>' + metrics.campaign.type_label + '</td></tr>' +
'<tr><td>Incident / Relevant Date</td><td>' + metrics.campaign.incident_date + '</td></tr>' +
'<tr><td>Notification Date</td><td>' + metrics.campaign.notification_date + '</td></tr>' +
'<tr><td>Jurisdiction</td><td>' + metrics.campaign.jurisdiction + '</td></tr>' +
'<tr><td>Rows Uploaded</td><td>' + metrics.summary.total_rows_uploaded + '</td></tr>' +
'<tr><td>Invalid Emails Skipped</td><td>' + metrics.summary.skipped_invalid + '</td></tr>' +
'<tr><td>Duplicates Removed</td><td>' + metrics.summary.duplicates_removed + '</td></tr>' +
'<tr><td>Compliance Deadline</td><td style="font-weight:bold;color:' + orange + ';">' + metrics.compliance.notification_deadline + '</td></tr>' +
'</tbody></table></div>' +
'<div class="section"><h2>Recipient Analysis</h2><table><thead><tr><th>Email Domain</th><th>Volume</th><th>Share</th></tr></thead><tbody>' + domainRows + '</tbody></table></div>' +
failureSection +
'<div class="section"><h2>Compliance Summary</h2><div style="background:#f0f4ff;padding:20px;border-left:5px solid ' + blue + ';">' +
'<p style="margin-top:0;"><strong>Regulatory Requirements:</strong> ' + metrics.compliance.regulatory_requirements + '</p>' +
'<p style="margin-bottom:0;"><strong>Timeline Performance:</strong> Notification process completed in ' + metrics.timing.duration_minutes + ' minutes.</p>' +
'</div></div>' +
'<div class="footer"><p>Report generated on ' + new Date(metrics.report_metadata.generated_at).toLocaleString() + '</p>' +
'<p>Generated by: ' + metrics.report_metadata.generated_by + '</p>' +
'<p>CONFIDENTIAL: This report contains sensitive legal and compliance data.</p></div>' +
'</body></html>';

const htmlBuffer = Buffer.from(htmlReport, 'utf-8');

return {
  binary: {
    data: {
      data: htmlBuffer.toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html',
      fileExtension: 'html'
    }
  },
  json: {
    reportTitle: reportTitle,
    reportRecipient: metrics.report_metadata.report_recipient,
    fileName: 'notification-report-' + dateStamp + '.pdf',
    metrics: metrics
  }
};

